   const client=supabase,links=tripLots.filter(l=>l.trip_id===t.id);
   const tripLotsData=[...new Map(links.map(l=>[l.agave_lot_id,lots.find(x=>x.id===l.agave_lot_id)])).values()].filter((x):x is Lot=>!!x);
